    H, W = len(g), len(g[0])
    cnt = Counter(x for r in g for x in r)
    bg = cnt.most_common(1)[0][0]

    # Find 2-line (full column/row with consistent non-bg color)
    line = None
    vert = None
    for c in range(W):
        col_val = g[0][c]
        if col_val != bg and all(g[r][c] == col_val for r in range(H)):
            line, vert = c, True
            break
    if line is None:
        for r in range(H):
            row_val = g[r][0]
            if row_val != bg and all(g[r][c] == row_val for c in range(W)):
                line, vert = r, False
                break

    # Find pattern color and cells
    others = [k for k in cnt if k not in (bg,)]
    line_color = None
    if vert:
        line_color = g[0][line]
    else:
        line_color = g[line][0]
    sc = None
    for k in others:
        if k != line_color:
            sc = k
            break

    cells = [(r, c) for r in range(H) for c in range(W) if g[r][c] == sc]

    if not cells:
        return g

    # Get pattern bounding box
    min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
    min_c, max_c = min(c for r, c in cells), max(c for r, c in cells)

    # Calculate shift and create output
    if vert:  # Vertical 2-line: pattern shifts LEFT
        shift = line - min_c + 1

        for r, c in cells:
            g[r][c] = bg

        for r, c in cells:
            new_c = c + shift
            if 0 <= new_c < W:
                g[r][new_c] = sc

        eight_pos = max_c - 2
    else:
