            if 0 <= new_r < H:
                g[new_r][c] = sc

        eight_pos = max_r

    if vert:
        for r in range(H):
            if g[r][eight_pos] == bg:
                g[r][eight_pos] = 8
    else:
        for c in range(W):
            if g[eight_pos][c] == bg:
                g[eight_pos][c] = 8

    return g

